FUNCTION_BLOCK FB_Debounce
VAR_INPUT
    In : BOOL;
    Time_ms : TIME := T#20ms;
END_VAR
VAR_OUTPUT
    Out : BOOL;
END_VAR
VAR
    Timer : TON;
END_VAR

Timer(IN := (In <> Out), PT := Time_ms);
IF Timer.Q THEN
    Out := In;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_AnalogScale
VAR_INPUT
    Raw : INT;
    RawMin : INT := 0;
    RawMax : INT := 27648;
    EngMin : REAL := 0.0;
    EngMax : REAL := 100.0;
END_VAR
VAR_OUTPUT
    Value : REAL;
    WireBreak : BOOL;
END_VAR

WireBreak := Raw < (RawMin - 1000);
Value := EngMin + (INT_TO_REAL(Raw - RawMin) / INT_TO_REAL(RawMax - RawMin)) * (EngMax - EngMin);
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_ForceWindow
VAR_INPUT
    Force_kN : REAL;
    Target_kN : REAL;
    Tol_pct : REAL := 10.0;
END_VAR
VAR_OUTPUT
    InWindow : BOOL;
    TooHigh : BOOL;
    TooLow : BOOL;
END_VAR
VAR
    Band : REAL;
END_VAR

Band := Target_kN * Tol_pct / 100.0;
TooHigh := Force_kN > (Target_kN + Band);
TooLow := Force_kN < (Target_kN - Band);
InWindow := NOT TooHigh AND NOT TooLow;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_RampSpeed
VAR_INPUT
    Target : REAL;
    AccelPerS : REAL := 10.0;
    DecelPerS : REAL := 20.0;
    CycleS : REAL := 0.01;
END_VAR
VAR_OUTPUT
    Output : REAL;
END_VAR

IF Output < Target THEN
    Output := MIN(Output + AccelPerS * CycleS, Target);
ELSIF Output > Target THEN
    Output := MAX(Output - DecelPerS * CycleS, Target);
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_WeightControl
VAR_INPUT
    Enable : BOOL;
    AvgWeight_mg : REAL;
    Target_mg : REAL;
    Kp : REAL := 0.002;
    Ki : REAL := 0.0005;
    CycleS : REAL := 1.0;
    MaxCorr_mm : REAL := 1.0;
END_VAR
VAR_OUTPUT
    Correction_mm : REAL;
    AtLimit : BOOL;
END_VAR
VAR
    Error : REAL;
    Integral : REAL;
END_VAR

IF NOT Enable THEN
    Integral := 0.0;
    Correction_mm := 0.0;
    AtLimit := FALSE;
    RETURN;
END_IF;

Error := Target_mg - AvgWeight_mg;
Integral := Integral + Error * Ki * CycleS;

// anti wind-up: stop integrating at the limit
Integral := LIMIT(-MaxCorr_mm, Integral, MaxCorr_mm);
Correction_mm := LIMIT(-MaxCorr_mm, Kp * Error + Integral, MaxCorr_mm);
AtLimit := ABS(Correction_mm) >= MaxCorr_mm;
END_FUNCTION_BLOCK

