// Machine states (PackML style): 0 Stopped, 1 Starting, 2 Execute, 3 Stopping, 4 Aborted
CASE State OF
    0: // stopped
        IF Cmd_Start AND GuardsOK AND NOT Fault_Active THEN State := 1; END_IF;

    1: // starting: let the drives and the feeder come up
        Start_Press := TRUE;
        StartTimer(IN := TRUE, PT := T#8s);
        IF StartTimer.Q THEN State := 2; END_IF;
        IF Fault_Active OR NOT GuardsOK THEN State := 4; END_IF;

    2: // execute: producing tablets
        StartTimer(IN := FALSE);
        IF Cmd_Stop THEN State := 3; END_IF;
        IF Fault_Active OR NOT GuardsOK THEN State := 4; END_IF;

    3: // stopping: ramp down
        Start_Press := FALSE;
        IF Press_Stopped THEN State := 0; END_IF;

    4: // aborted: needs a deliberate reset
        Start_Press := FALSE;
        IF Cmd_Reset AND GuardsOK AND NOT Fault_Active THEN State := 0; END_IF;
END_CASE;

Mode := State;

equipmentModules.code:
// Feeder speed follows the hopper level and the fill demand
FeedingReady := NOT Hopper_Empty AND NOT Feeder_Fault;

IF FeedingReady AND Compressing THEN
    Feeder_SP_rpm := LIMIT(20.0, Fill_Demand_pct * 1.2, 120.0);
ELSE
    Feeder_SP_rpm := 0.0;
END_IF;

Refill_Request := Hopper_Low;

// Press sequence: start the turret, wait for speed, then watch the force
CASE Step OF
    0: // idle
        Compressing := FALSE;
        Turret_Run := FALSE;
        IF Cmd_Start AND GuardsOK THEN Step := 10; END_IF;

    10: // start the turret
        Turret_Run := TRUE;
        IF Turret_AtSpeed THEN Step := 20; END_IF;
        IF Cmd_Stop OR NOT GuardsOK THEN Step := 40; END_IF;

    20: // producing
        Compressing := TRUE;
        IF Force_Out_Of_Band THEN Step := 30; END_IF;
        IF Cmd_Stop OR NOT GuardsOK THEN Step := 40; END_IF;

    30: // force out of band: reject until it recovers
        Reject_All := TRUE;
        IF NOT Force_Out_Of_Band THEN
            Reject_All := FALSE;
            Step := 20;
        END_IF;
        IF Cmd_Stop OR NOT GuardsOK THEN Step := 40; END_IF;

    40: // stopping
        Compressing := FALSE;
        Reject_All := FALSE;
        Turret_Run := FALSE;
        IF Turret_Stopped THEN Step := 0; END_IF;
END_CASE;

// Tablets are dedusted, counted and sorted
Deduster_Run := Compressing;
Gate_Reject := Reject_All OR Metal_Detected OR Weight_Out_Of_Spec;

RejectEdge(CLK := Gate_Reject AND TabletPresent);
IF RejectEdge.Q THEN
    RejectCount := RejectCount + 1;
END_IF;

// the reject gate must follow the request within the timeout
GateFault := Gate_Reject AND NOT Gate_InReject AND GateTimer.Q;

// The press runs only with every guard closed and the emergency stop released
GuardsOK := Door_Front_OK AND Door_Rear_OK AND NOT EStop_Active;

IF NOT GuardsOK THEN
    Stop_Request := TRUE;
ELSIF Reset_Cmd THEN
    Stop_Request := FALSE;
END_IF;

controlModules.code:
IF Cmd_Run AND NOT Fault THEN
    Out_Enable := TRUE;
    Out_SpeedRef := LIMIT(0.0, Speed_SP_rpm, 90.0) / 90.0 * 100.0;
ELSE
    Out_Enable := FALSE;
    Out_SpeedRef := 0.0;
END_IF;

// the drive must confirm running within 3 s
FeedbackTimer(IN := Out_Enable AND NOT In_Running, PT := T#3s);
Fault := FeedbackTimer.Q;

Scale(Raw := In_Raw, EngMin := 0.0, EngMax := 100.0);
Level_pct := Scale.Value;
WireBreak := Scale.WireBreak;
LowLevel := Level_pct < 20.0;
Empty := Level_pct < 5.0;

Ramp(Target := Speed_SP_rpm, AccelPerS := 5.0, DecelPerS := 15.0);
IF Cmd_Run AND NOT Fault THEN
    Out_Enable := TRUE;
    Out_SpeedRef := Ramp.Output;
ELSE
    Out_Enable := FALSE;
    Out_SpeedRef := 0.0;
END_IF;

// the drive must confirm running within 5 s
FeedbackTimer(IN := Out_Enable AND NOT In_Running, PT := T#5s);
Fault := FeedbackTimer.Q;

ScaleMain(Raw := In_Raw_Main, EngMin := 0.0, EngMax := 100.0);
ScalePre(Raw := In_Raw_Pre, EngMin := 0.0, EngMax := 30.0);
Force_Main_kN := ScaleMain.Value;
Force_Pre_kN := ScalePre.Value;
WireBreak := ScaleMain.WireBreak OR ScalePre.WireBreak;

Window(Force_kN := Force_Main_kN, Target_kN := Target_kN, Tol_pct := Tol_pct);
ForceHigh := Window.TooHigh;
ForceLow := Window.TooLow;
Overload := Force_Main_kN > 90.0;

IF Cmd_Move AND In_Ready AND NOT Fault THEN
    Out_Pos_SP := LIMIT(2.0, Pos_SP_mm, 20.0);
    Out_Start := TRUE;
ELSE
    Out_Start := FALSE;
END_IF;

OutOfRange := (Pos_SP_mm < 2.0) OR (Pos_SP_mm > 20.0);
Fault := NOT In_Ready AND Out_Start;

// slow weight correction from the average tablet weight
WeightCtl(Enable := WeightCtl_On, AvgWeight_mg := AvgWeight_mg, Target_mg := Target_mg);
Out_Pos_SP := LIMIT(2.0, Out_Pos_SP + WeightCtl.Correction_mm, 20.0);

Out_Run := Cmd_Run AND NOT Fault;
FeedbackTimer(IN := Out_Run AND NOT In_Running, PT := T#3s);
Fault := FeedbackTimer.Q;

IF Cmd_Reject THEN
    Out_Valve := TRUE;
END_IF;
IF NOT Cmd_Reject AND In_Safe THEN
    Out_Valve := FALSE;
END_IF;

MoveTimer(IN := Out_Valve XOR In_Reject, PT := T#500ms);
Fault := MoveTimer.Q;

Filter(In := In_Raw, Time_ms := T#5ms);
TabletPresent := Filter.Out;
IF TabletPresent AND NOT Last THEN
    Count := Count + 1;
END_IF;
Last := TabletPresent;

Out_SafetyOK := In_Door_Ch1 AND In_Door_Ch2;

// the two channels must agree within 1 s
DiscTimer(IN := In_Door_Ch1 <> In_Door_Ch2, PT := T#1s);
Discrepancy := DiscTimer.Q;

PulseTimer(IN := NOT Out_Pump, PT := T#30m);
RunTimer(IN := Out_Pump, PT := T#10s);
Out_Pump := PulseTimer.Q AND NOT RunTimer.Q;
